target.expr:
max by (name) (
  (
    co_rsk_metrics_Jmx_profiler_Duration{
      exported_name="BLOCK_EXECUTE",
      name=~"$container"
    } / 1e9
  )
  or
  (
    co_rsk_metrics_Jmx_profiler_Duration{
      exported_name="AFTER_BLOCK_EXEC",
      name=~"$container"
    } / 1e9
  )
  or
  (
    co_rsk_metrics_Jmx_profiler_Duration{
      exported_name="BEFORE_BLOCK_EXEC",
      name=~"$container"
    } / 1e9
  )
  or
  (
    co_rsk_metrics_Jmx_profiler_Duration{
      exported_name="BLOCK_TXS_VALIDATION",
      name=~"$container"
    } / 1e9
  )
  or
  (
    promtail_custom_block_processed_after_seconds{container_id=~"$container"}
  )
) > 2

